/* MIT. Bounded single-scene playback. Map actors/encounters are a separate adapter.
 * Only dialogue acknowledgements move checkpoints; skipping never invents events. */
#ifndef MYRO_CAMPAIGN_SCENE200_H
#define MYRO_CAMPAIGN_SCENE200_H
#include "campaign_state200.h"
#include "chapter1_data200.h"
enum{SC200_ERROR=-1,SC200_CLOSED,SC200_LINE,SC200_CHOICE,SC200_WAIT,SC200_ROLE,SC200_COMPLETE,SC200_GUILD};
typedef int(*SceneRead200)(void*,unsigned,unsigned char*,unsigned);
typedef struct{NpcState55*state;unsigned char*data;unsigned bytes,count,pool,cursor;int status;}Scene200;
static void scene_close200(Scene200*r){free(r->data);memset(r,0,sizeof(*r));}
static unsigned scene_u16_200(const unsigned char*p){return p[0]|(unsigned)p[1]<<8;}
static const unsigned char*scene_node200(const Scene200*r,unsigned node){return r->data+16+node*32;}
static int scene_target200(unsigned target,unsigned count){return target==65535||target<count;}
static int scene_validate200(const unsigned char*p,unsigned bytes,unsigned cursor){if(bytes<17||bytes>16384||memcmp(p,"RSC2",4)||scene_u16_200(p+4)!=1||scene_u16_200(p+12)!=cursor||scene_u16_200(p+14))return 0;unsigned count=scene_u16_200(p+6),pool=npc_state_u32_55(p+8);if(!count||count>64||!pool||16+count*32>bytes||pool!=bytes-16-count*32)return 0;const unsigned char*text=p+16+count*32;for(unsigned i=0;i<count;i++){const unsigned char*n=p+16+i*32;if(n[0]<1||n[0]>8||n[1]>7||!scene_target200(scene_u16_200(n+2),count)||!scene_target200(scene_u16_200(n+20),count)||!scene_target200(scene_u16_200(n+22),count)||(npc_state_u32_55(n+28)>0x50ffu||(npc_state_u32_55(n+28)&255u)>5u))return 0;for(unsigned j=4;j<20;j+=4){unsigned at=npc_state_u32_55(n+j);if(at>=pool||!memchr(text+at,0,pool-at))return 0;}if(n[0]==7&&(!npc_state_u32_55(n+24)||npc_state_u32_55(n+24)>=(1u<<CAMPAIGN_COMPANIONS200)))return 0;if(n[0]==2&&(scene_u16_200(n+20)==65535||scene_u16_200(n+22)==65535))return 0;if(n[0]!=4&&n[0]!=6&&n[0]!=2&&scene_u16_200(n+2)==65535)return 0;}return 1;}
static int scene_inflate200(unsigned char*out,unsigned raw,const unsigned char*cp,unsigned packed){z_stream z={0};
#ifndef MYRO_HOST
 z.zalloc=asset_zalloc;z.zfree=asset_zfree;
#endif
 z.next_in=(unsigned char*)cp;z.avail_in=packed;z.next_out=out;z.avail_out=raw;int ok=inflateInit(&z)==Z_OK;if(ok){ok=inflate(&z,Z_FINISH)==Z_STREAM_END&&z.total_out==raw&&!z.avail_in;inflateEnd(&z);}return ok;}
static int scene_open200(Scene200*r,NpcState55*state,SceneRead200 read,void*context){Campaign200 c;if(!r||!state||!read||campaign_load200(state,&c)!=1||c.cursor>=CAMPAIGN_RELEASE_SCENES193)return 0;unsigned which=c.cursor,packed=chapter1Index200[which].packed,raw=chapter1Index200[which].raw;if(!packed||packed>8192||raw>16384||chapter1Index200[which].offset>CHAPTER1_FILE_BYTES200||packed>CHAPTER1_FILE_BYTES200-chapter1Index200[which].offset)return 0;unsigned char*cp=malloc(packed),*out=malloc(raw);if(!cp||!out){free(cp);free(out);return 0;}int ok=read(context,chapter1Index200[which].offset,cp,packed)&&scene_inflate200(out,raw,cp,packed)&&crc32(0,out,raw)==chapter1Index200[which].crc&&scene_validate200(out,raw,which);free(cp);if(!ok){free(out);return 0;}unsigned count=scene_u16_200(out+6);if(c.checkpoint>=count){free(out);return 0;}scene_close200(r);r->data=out;r->state=state;r->bytes=raw;r->count=count;r->pool=16+count*32;r->cursor=which;r->status=SC200_LINE;return 1;}
static int scene_move200(Scene200*r,unsigned next){if(next>=r->count||!campaign_checkpoint200(r->state,r->cursor,next))return 0;return 1;}
static int scene_poll200(Scene200*r){if(!r||!r->data)return r?r->status:SC200_ERROR;for(unsigned hops=0;hops<64;hops++){Campaign200 c;if(campaign_load200(r->state,&c)!=1||c.cursor!=r->cursor||c.checkpoint>=r->count)return r->status=SC200_ERROR;const unsigned char*n=scene_node200(r,c.checkpoint);unsigned kind=n[0],mask=n[1],next=scene_u16_200(n+2);if(mask){if(!c.route)return r->status=SC200_ROLE;if(!(mask&(1u<<(c.route-1)))){if(!scene_move200(r,next))return r->status=SC200_ERROR;continue;}}if(kind==1)return r->status=SC200_LINE;if(kind==2)return r->status=SC200_CHOICE;if(kind==3){unsigned required=npc_state_u32_55(n+24);if((c.objectives&required)!=required)return r->status=SC200_WAIT;}else if(kind==5){if(!c.route)return r->status=SC200_ROLE;}else if(kind==4){unsigned required=npc_state_u32_55(n+24);if(!required&&!campaign_objective200(r->state,r->cursor,0))return r->status=SC200_ERROR;if(!campaign_advance200(r->state,r->cursor,required))return r->status=SC200_WAIT;scene_close200(r);return r->status=SC200_COMPLETE;}else if(kind==8){if(!c.guild[0])return r->status=SC200_GUILD;}else if(kind==7){if(!campaign_join200(r->state,r->cursor,npc_state_u32_55(n+24)))return r->status=SC200_ERROR;}else if(kind==6){if(!campaign_checkpoint200(r->state,r->cursor,0))return r->status=SC200_ERROR;scene_close200(r);return r->status=SC200_CLOSED;}if(!scene_move200(r,next))return r->status=SC200_ERROR;}return r->status=SC200_ERROR;}
static const char*scene_text200(Scene200*r,unsigned field){if(field>3||!r||!r->data)return "";Campaign200 c;if(campaign_load200(r->state,&c)!=1||c.cursor!=r->cursor||c.checkpoint>=r->count)return "";return(const char*)r->data+r->pool+npc_state_u32_55(scene_node200(r,c.checkpoint)+4+field*4);}
/* Expression lives in the node, so save/reopen follows the same checkpoint. */
static unsigned scene_expression200(const Scene200*r){Campaign200 c;if(!r||!r->data||campaign_load200(r->state,&c)!=1||c.cursor!=r->cursor||c.checkpoint>=r->count)return 0;return npc_state_u32_55(scene_node200(r,c.checkpoint)+28)&255u;}
/* Released node word: low byte expression; upper byte preserves the emotion cue. */
static unsigned scene_emotion195(const Scene200*r){Campaign200 c;if(!r||!r->data||campaign_load200(r->state,&c)!=1||c.cursor!=r->cursor||c.checkpoint>=r->count)return 0;return npc_state_u32_55(scene_node200(r,c.checkpoint)+28)>>8;}
/* SAY requires0; CHOICE accepts0/1. A gate cannot be acknowledged away. */
static int scene_next200(Scene200*r,unsigned answer){int status=scene_poll200(r);if(status!=SC200_LINE&&status!=SC200_CHOICE)return status;if(answer>(status==SC200_CHOICE?1u:0u))return SC200_ERROR;Campaign200 c;if(campaign_load200(r->state,&c)!=1)return SC200_ERROR;const unsigned char*n=scene_node200(r,c.checkpoint);unsigned next=scene_u16_200(n+(status==SC200_CHOICE?20+answer*2:2));if(!scene_move200(r,next))return r->status=SC200_ERROR;return scene_poll200(r);}
/* Skip only ordinary lines. Choices, physical objectives and role consent stop it. */
static int scene_skip_lines200(Scene200*r){for(unsigned i=0;i<64;i++){int status=scene_poll200(r);if(status!=SC200_LINE)return status;status=scene_next200(r,0);if(status!=SC200_LINE)return status;}return r->status=SC200_ERROR;}
#endif
